#include <cmath>
#include <cstdio>
#include <vector>

// Explicit finite-difference backward sweep for a European put (S-space grid).
int main() {
    const double Smax = 200.0, K = 100.0, r = 0.05, sigma = 0.25, T = 1.0;
    const double dS = 20.0;
    for (double dt : {0.025, 0.25}) {                 // stable vs unstable choice
        const int J = int(Smax / dS);                 // 10 interior strips, nodes 0..10
        const int nSteps = int(T / dt);
        std::vector<double> V(J + 1), Vn(J + 1);
        for (int j = 0; j <= J; ++j) V[j] = std::max(K - j * dS, 0.0);   // payoff
        for (int n = 0; n < nSteps; ++n) {
            Vn[0] = K * std::exp(-r * (n + 1) * dt);  // S=0 boundary: discounted strike
            Vn[J] = 0.0;                              // put is worthless at Smax
            for (int j = 1; j < J; ++j) {
                const double a = 0.5 * dt * (sigma * sigma * j * j - r * j);
                const double b = 1.0 - dt * (sigma * sigma * j * j + r);
                const double c = 0.5 * dt * (sigma * sigma * j * j + r * j);
                Vn[j] = a * V[j - 1] + b * V[j] + c * V[j + 1];
            }
            std::swap(V, Vn);
        }
        std::printf("dt=%.3f  V(S=100)=%8.4f   b(j=10)=%.3f\n", dt, V[5],
                    1.0 - dt * (sigma * sigma * 100.0 + r));
    }
    return 0;
}
